    # --- next occurrence table: nxt[(q * 26) + c] = first pos >= q with
    #     s[pos] == c, or n if absent --------------------------------------
    nxt = [n] * ((n + 1) * 26)
    for q in range(n - 1, -1, -1):
        row = q * 26
        nxtrow = (q + 1) * 26
        for c in range(26):
            nxt[row + c] = nxt[nxtrow + c]
        nxt[row + a[q]] = q

    # --- memoized suffix value ---------------------------------------------
    # H(j, D) = number of cuts the greedy scan makes in s[j..n) when the
    # current window already contains exactly the distinct letters D
    # (|D| <= k). >> Pure function of the suffix and the mask, shared by all
    # candidate evaluations.
    memo = {}

    def H(j, D):
        acc = 0
        path = []
        while True:
            key = (j, D)
            cached = memo.get(key)
            if cached is not None:
                acc = cached
                break
            path.append(key)
            row = j * 26
            p = n
            nd = ~D
            while nd:
                low = nd & -nd
                c = low.bit_length() - 1
                pos = nxt[row + c]
                if pos < p:
                    p = pos
                nd ^= low
            if p == n:
                acc = 0
                break
            if D.bit_count() < k:
                j, D = p, D | (1 << a[p])
                path[-1] = (path[-1][0], path[-1][1], 0)
            else:
                j, D = p + 1, 1 << a[p]
                path[-1] = (path[-1][0], path[-1][1], 1)
        for entry in reversed(path):
            if len(entry) == 3 and entry[2]:
                acc += 1
            memo[entry[:2]] = acc
        return acc

